          '**Tratamiento de datos en DigitalOcean:** su [acuerdo de tratamiento de datos](https://www.digitalocean.com/legal/data-processing-agreement) cubre el RGPD; para transferencias fuera del EEE se apoya en la certificación del EU-U.S. Data Privacy Framework y, en su defecto, en Cláusulas Contractuales Tipo. La propia página de GPU Droplets no hace ninguna declaración sobre el RGPD, y dice que los GPU Droplets cumplen SOC 2 y son aptos para HIPAA.',
          '**UpCloud:** PromptQuorum no pudo leer las páginas de seguridad y privacidad de UpCloud el 2026-11-22 (la obtención devolvió un error), así que confirma directamente que la ubicación de GPU que elijas está en la UE antes de fiarte. Sus docs no indican qué regiones ofrecen GPUs spot.',
